from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    def line_mode(values):
        return Counter(values).most_common(1)[0][0]

    row_lines = []
    for r in range(h):
        values = grid[r]
        mode = line_mode(values)
        if mode != background and any(x != mode for x in values):
            row_lines.append(r)

    col_lines = []
    for c in range(w):
        values = [grid[r][c] for r in range(h)]
        mode = line_mode(values)
        if mode != background and any(x != mode for x in values):
            col_lines.append(c)

    result = []
    for i in range(len(row_lines) - 1):
        row = []
        for j in range(len(col_lines) - 1):
            r1, r2 = row_lines[i], row_lines[i + 1]
            c1, c2 = col_lines[j], col_lines[j + 1]
            corners = [grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2]]
            row.append(corners[0] if all(x == corners[0] for x in corners)
                       else background)
        result.append(row)
    return result
